def solve(x):
    edges = x["edges"]
    start = x["start"]
    visited = set()
    result = set()

    def dfs(node):
        if node == start:
            return
        visited.add(node)
        result.add(node)
        for neighbor in edges:
            if neighbor[0] == node:
                dfs(neighbor[1])
            elif neighbor[1] == node:
                dfs(neighbor[0])

    dfs(start)
    return sorted(result - {start})
